def calculate_an(n):
    memo = {}

    def a(k):
        if k in memo:
            return memo[k]
        if k == 1:
            return 0

        if k % 2 == 0:
            # Even case: a_n = 2*a_{n/2} + n/2
            result = 2 * a(k // 2) + k // 2
        else:
            # Odd case: a_n = a_{floor(n/2)} + a_{ceil(n/2)} + floor(n/2)
            m = k // 2  # m = floor(k/2)
            m_plus_1 = k - m # m_plus_1 = ceil(k/2)
            result = a(m) + a(m_plus_1) + m

        memo[k] = result
        return result

    return a(n)

# Calculate a_2025
N = 2025
a_2025 = calculate_an(N)

print(f"a_{N} = {a_2025}")
